import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static String s;
    static List<Integer>[] g;
    static int[] sz, r;
    static int ans = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        s = " " + br.readLine().trim();  // 1-based
        g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            g[i] = new ArrayList<>();
        }
        for (int i = 0; i < n - 1; i++) {
            String[] edge = br.readLine().split(" ");
            int u = Integer.parseInt(edge[0]);
            int v = Integer.parseInt(edge[1]);
            g[u].add(v);
            g[v].add(u);
        }
        sz = new int[n + 1];
        r = new int[n + 1];

        dfs1(1, 0);
        ans = 0;
        dfs2(1, 0);
        System.out.println(ans);
    }

    static void dfs1(int u, int p) {
        sz[u] = 1;
        r[u] = s.charAt(u) == 'R' ? 1 : 0;
        for (int v : g[u]) {
            if (v == p) continue;
            dfs1(v, u);
            sz[u] += sz[v];
            r[u] += r[v];
        }
    }

    static void dfs2(int u, int p) {
        for (int v : g[u]) {
            if (v == p) continue;
            // 检查边 (u, v)
            if (r[v] > sz[v] - r[v]) {
                int restR = r[1] - r[v];
                int restSz = n - sz[v];
                if (restR > restSz - restR) {
                    ans++;
                }
            }
            dfs2(v, u);
        }
    }
}
